const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const toliara = ee.Geometry.Point([43.685, -23.351]); // Toliara, Madagascar
  const region = toliara.buffer(10000); // 10km buffer for regional average

  const baselineStart = '2000-09-01';
  const baselineEnd = '2015-09-30';
  const targetStart = '2021-09-01';
  const targetEnd = '2022-09-30';

  // 2. Data Acquisition - MODIS NDVI for consistent long-term data
  const getSeptNDVI = function(startDate, endDate) {
    const col = ee.ImageCollection('MODIS/061/MOD13Q1')
      .filterDate(startDate, endDate)
      .filterBounds(region)
      .select('NDVI');

    if (col.size().getInfo() === 0) {
      return null;
    }

    // Scale NDVI values (-2000 to 10000) to -1 to 1
    const scaled = col.mean().multiply(0.0001);

    // Mask low quality (SummaryQA != 0) - using the pixel reliability band
    // MOD13Q1 doesn't have SummaryQA, using VI Quality band instead
    const mask = col.select('SummaryQA').mean().eq(0);
    return scaled.updateMask(mask);
  };

  // Get baseline (2000-2015) and target (2021-2022) NDVI
  const baselineImg = getSeptNDVI(baselineStart, baselineEnd);
  const targetImg = getSeptNDVI(targetStart, targetEnd);

  // Check for empty collections
  if (!baselineImg || !targetImg) {
    const baselineCount = ee.ImageCollection('MODIS/061/MOD13Q1')
      .filterDate(baselineStart, baselineEnd)
      .filterBounds(region).size().getInfo();
    const targetCount = ee.ImageCollection('MODIS/061/MOD13Q1')
      .filterDate(targetStart, targetEnd)
      .filterBounds(region).size().getInfo();

    console.log(`Baseline images: ${baselineCount}`);
    console.log(`Target images: ${targetCount}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate regional averages
  const baselineMean = baselineImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetMean = targetImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // Count valid pixels
  const baselineCount = baselineImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetCount = targetImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Baseline NDVI (2000-2015): ${baselineMean ? baselineMean.toFixed(3) : 'null'}, Valid pixels: ${baselineCount}`);
  console.log(`Target NDVI (2021-2022): ${targetMean ? targetMean.toFixed(3) : 'null'}, Valid pixels: ${targetCount}`);

  // 4. Check for no valid pixels
  if (baselineCount === 0 || targetCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validate results and determine answer
  if (baselineMean === null || targetMean === null || 
      isNaN(baselineMean) || isNaN(targetMean) ||
      baselineMean > 1 || baselineMean < -1 || 
      targetMean > 1 || targetMean < -1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Final comparison
  const decreasePercent = ((baselineMean - targetMean) / baselineMean * 100).toFixed(1);
  console.log(`Change: ${decreasePercent}%`);

  if (targetMean < baselineMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
